class Solution {
public:
    int semiOrderedPermutation(vector<int>& nums) {
        int n = nums.size();
        int i = 0, j = 0;
        for (int k = 0; k < n; ++k) {
            if (nums[k] == 1) i = k;
            if (nums[k] == n) j = k;
        }
        return i + (n - 1 - j) - (i > j ? 1 : 0);
    }
};

class Solution {
    public int semiOrderedPermutation(int[] nums) {
        int n = nums.length;
        int i = 0, j = 0;
        for (int k = 0; k < n; k++) {
            if (nums[k] == 1) i = k;
            if (nums[k] == n) j = k;
        }
        return i + (n - 1 - j) - (i > j ? 1 : 0);
    }
}

var semiOrderedPermutation = function(nums) {
    const n = nums.length;
    const i = nums.indexOf(1);
    const j = nums.indexOf(n);
    return i + (n - 1 - j) - (i > j ? 1 : 0);
};
